/* Critical sections map to recursive pthread mutexes (Win32 CS are recursive). */
typedef pthread_mutex_t CRITICAL_SECTION;
static inline void InitializeCriticalSection(CRITICAL_SECTION *cs) {
    pthread_mutexattr_t a; pthread_mutexattr_init(&a);
    pthread_mutexattr_settype(&a, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(cs, &a); pthread_mutexattr_destroy(&a);
}
static inline BOOL InitializeCriticalSectionAndSpinCount(CRITICAL_SECTION *cs, DWORD spin) { (void)spin; InitializeCriticalSection(cs); return TRUE; }
static inline void EnterCriticalSection(CRITICAL_SECTION *cs) { pthread_mutex_lock(cs); }
static inline BOOL TryEnterCriticalSection(CRITICAL_SECTION *cs) { return pthread_mutex_trylock(cs) == 0; }
static inline void LeaveCriticalSection(CRITICAL_SECTION *cs) { pthread_mutex_unlock(cs); }
static inline void DeleteCriticalSection(CRITICAL_SECTION *cs) { pthread_mutex_destroy(cs); }

/* Interlocked operations on 32-bit LONG via compiler atomics. */
static inline LONG InterlockedIncrement(volatile LONG *p) { return __atomic_add_fetch(p, 1, __ATOMIC_SEQ_CST); }
static inline LONG InterlockedDecrement(volatile LONG *p) { return __atomic_sub_fetch(p, 1, __ATOMIC_SEQ_CST); }
static inline LONG InterlockedExchange(volatile LONG *p, LONG v) { return __atomic_exchange_n(p, v, __ATOMIC_SEQ_CST); }
static inline LONG InterlockedExchangeAdd(volatile LONG *p, LONG v) { return __atomic_fetch_add(p, v, __ATOMIC_SEQ_CST); }
static inline LONG InterlockedCompareExchange(volatile LONG *p, LONG exch, LONG comp) {
    __atomic_compare_exchange_n(p, &comp, exch, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST); return comp;
}

/* Secure CRT subset. */
static inline int fopen_s(FILE **f, const char *name, const char *mode) { *f = fopen(name, mode); return *f ? 0 : errno; }
static inline int strcpy_s(char *d, size_t n, const char *s) { if (!d || !n) return EINVAL; cf_strlcpy(d, s ? s : "", n); return 0; }
static inline int strcat_s(char *d, size_t n, const char *s) { size_t l = strnlen(d, n); if (l >= n) return EINVAL; cf_strlcpy(d + l, s ? s : "", n - l); return 0; }
static inline int localtime_s(struct tm *r, const time_t *t) { return localtime_r(t, r) ? 0 : EINVAL; }
static inline int gmtime_s(struct tm *r, const time_t *t) { return gmtime_r(t, r) ? 0 : EINVAL; }
#define sprintf_s snprintf
#define vsprintf_s vsnprintf

/* Executable path. */
static inline DWORD GetModuleFileNameA(HMODULE m, LPSTR buf, DWORD size) {
    (void)m; const char *p = cf_executable_path(); if (!buf || !size) return 0;
    cf_strlcpy(buf, p, size); return (DWORD)strlen(buf);
}
#define GetModuleFileName GetModuleFileNameA

/* WinSock subset: sockets are plain fds on POSIX. */
typedef int SOCKET;
#define INVALID_SOCKET (-1)
#define SOCKET_ERROR (-1)
#define closesocket(s) close(s)
#define ioctlsocket(s, cmd, argp) ioctl((s), (cmd), (argp))
typedef struct { WORD wVersion; WORD wHighVersion; char szDescription[257]; char szSystemStatus[129]; } WSADATA;
#define MAKEWORD(a, b) ((WORD)(((BYTE)(a)) | (((WORD)((BYTE)(b))) << 8)))
static inline int WSAStartup(WORD v, WSADATA *d) { (void)v; if (d) memset(d, 0, sizeof *d); return 0; }
static inline int WSACleanup(void) { return 0; }
#define WSAGetLastError() errno
#endif /* Win32 compat */

/* ===================================================== POSIX compatibility */
#if defined(_WIN32) && !defined(CF_NO_POSIX_COMPAT)
#  define strcasecmp _stricmp
#  define strncasecmp _strnicmp
#  if defined(_MSC_VER)
#    include <BaseTsd.h>
typedef SSIZE_T ssize_t;
#    ifndef PATH_MAX
#      define PATH_MAX MAX_PATH
#    endif
#    define popen _popen
#    define pclose _pclose
#    define usleep(us) cf_sleep_us((uint64_t)(us))
#    define sleep(s) cf_sleep_ms((uint32_t)(s) * 1000u)
static inline int setenv(const char *n, const char *v, int overwrite) {
    if (!overwrite && getenv(n)) return 0; return _putenv_s(n, v);
}
static inline int unsetenv(const char *n) { return _putenv_s(n, ""); }
#    ifndef CLOCK_MONOTONIC
#      define CLOCK_REALTIME 0
#      define CLOCK_MONOTONIC 1
typedef int clockid_t;
static inline int clock_gettime(clockid_t id, struct timespec *ts) {
    if (id == CLOCK_MONOTONIC) {
        uint64_t ns = cf_ticks_ns(); ts->tv_sec = (time_t)(ns / 1000000000ull); ts->tv_nsec = (long)(ns % 1000000000ull);
        return 0;
    }
    return timespec_get(ts, TIME_UTC) ? 0 : -1;
}
#    endif
#  endif
#endif /* POSIX compat */

